76	-- ---------------------------------------------------------------------------------------------
77	-- record_payment (R19-R22, D9): manual cash / bank transfer payment.
78	-- ---------------------------------------------------------------------------------------------
79	create or replace function private.record_payment(
80	  p_actor_id uuid,
81	  p_lease_id uuid,
82	  p_amount_sen bigint,
83	  p_method text,
84	  p_received_at timestamptz,
85	  p_slip_path text,
86	  p_idempotency_key uuid
87	)
88	returns table(id uuid, status text, replayed boolean)
89	language plpgsql
90	security invoker
91	set search_path = ''
92	as $$
93	#variable_conflict use_column
94	declare
95	  v_lease record;
96	  v_role text;
97	  v_existing record;
98	  v_status text;
99	  v_cap bigint;
100	  v_id uuid;
101	begin
102	  -- D7: the cap is computed after the lease lock; READ COMMITTED gives each statement a fresh snapshot after the wait
103	  if current_setting('transaction_isolation') <> 'read committed' then
104	    raise exception using errcode = 'P0409', message = 'Unsupported isolation level';
105	  end if;
106	
107	  -- D7: lease lock first; concurrent recordings on one lease queue here, so the cap below is
108	  -- computed against everything committed before us (R28).
109	  select l.id, l.org_id
110	    into v_lease
111	    from public.leases l
112	   where l.id = p_lease_id
113	     for update;
114	  if not found then
115	    raise exception using errcode = 'P0404', message = 'Lease not found';
116	  end if;
117	
118	  select m.role
119	    into v_role
120	    from public.memberships m
121	   where m.user_id = p_actor_id
122	     and m.org_id = v_lease.org_id
123	     and m.role in ('manager', 'staff');
124	  if v_role is null then
125	    -- R38/D15: same message as a missing lease, never reveal that it exists in another org.
126	    raise exception using errcode = 'P0404', message = 'Lease not found';
127	  end if;
128	
129	  -- D9: replay check before validation, so a retry of an accepted request returns the original
130	  -- even if the payment has since been approved/rejected/voided or the cap is now used up.
131	  if p_idempotency_key is not null then
132	    select p.id, p.status, p.lease_id, p.amount_sen, p.method, p.received_at, p.slip_path
133	      into v_existing
134	      from public.payments p
135	     where p.org_id = v_lease.org_id
136	       and p.idempotency_key = p_idempotency_key;
137	    if found then
138	      if v_existing.lease_id = p_lease_id
139	         and v_existing.amount_sen = p_amount_sen
140	         and v_existing.method = p_method
141	         and v_existing.received_at = p_received_at
142	         and v_existing.slip_path is not distinct from p_slip_path then
143	        return query select v_existing.id, v_existing.status, true;
144	        return;
145	      end if;
146	      raise exception using errcode = 'P0409', message = 'Idempotency key reused with a different payload';
147	    end if;
148	  end if;
149	
150	  if p_method is null or p_method not in ('cash', 'bank_transfer') then
151	    raise exception using errcode = 'P0400', message = 'Invalid payment method';
152	  end if;
153	  if p_amount_sen is null or p_amount_sen <= 0 then
154	    raise exception using errcode = 'P0400', message = 'Amount must be a positive number of sen';
155	  end if;
156	  if p_received_at is null then
157	    raise exception using errcode = 'P0400', message = 'Received time is required';
158	  end if;
159	  if p_method = 'cash' and p_slip_path is not null then
160	    raise exception using errcode = 'P0400', message = 'A cash payment cannot have a slip';
161	  end if;
162	  if p_method = 'bank_transfer' then
163	    -- R44/D22: the slip must be an uploaded object in this lease's org folder; a path in another
164	    -- org's folder gets the same message as a missing file.
165	    if p_slip_path is null
166	       or not exists (select 1
167	                        from storage.objects o
168	                       where o.bucket_id = 'payment-slips'
169	                         and o.name = p_slip_path
170	                         and split_part(o.name, '/', 1) = v_lease.org_id::text
171	                         and o.name like v_lease.org_id::text || '/%') then
172	      raise exception using errcode = 'P0400', message = 'Slip file not found';
173	    end if;
174	    -- D22: a slip already backing another payment is invalid input (400), not a state conflict.
175	    if exists (select 1 from public.payments p where p.slip_path = p_slip_path) then
176	      raise exception using errcode = 'P0400', message = 'Slip already used';
177	    end if;
178	  end if;
179	
180	  -- R22/D13: cap = all invoices - all allocations - pending payments of this lease, read after
181	  -- the lock. Voided payments have no allocations left, rejected ones are not pending.
182	  select (select coalesce(sum(i.amount_sen), 0) from public.invoices i where i.lease_id = p_lease_id)
183	       - (select coalesce(sum(a.amount_sen), 0) from public.payment_allocations a where a.lease_id = p_lease_id)
184	       - (select coalesce(sum(p.amount_sen), 0) from public.payments p
185	           where p.lease_id = p_lease_id and p.status = 'pending_verification')
186	    into v_cap;
187	  if p_amount_sen > v_cap then
188	    raise exception using errcode = 'P0422', message = 'Payment exceeds the remaining balance';
189	  end if;
190	
191	  -- R21: manager-recorded payments are approved immediately, staff ones wait for a manager.
192	  v_status := case when v_role = 'manager' then 'approved' else 'pending_verification' end;
193	
194	  -- D9: ON CONFLICT DO NOTHING + re-select turns a race on (org_id, idempotency_key) or slip_path
195	  -- (another lease of the org, not serialized by our lease lock) into a replay / 409, never a 500.
196	  insert into public.payments as p
197	         (org_id, lease_id, amount_sen, method, status, received_at, slip_path,
198	          idempotency_key, recorded_by, decided_by, decided_at)
199	  values (v_lease.org_id, p_lease_id, p_amount_sen, p_method, v_status, p_received_at, p_slip_path,
200	          p_idempotency_key, p_actor_id,
201	          case when v_status = 'approved' then p_actor_id end,
202	          case when v_status = 'approved' then now() end)
203	  on conflict do nothing
204	  returning p.id into v_id;
205	
206	  if v_id is null then
207	    if p_idempotency_key is not null then
208	      select p.id, p.status, p.lease_id, p.amount_sen, p.method, p.received_at, p.slip_path
209	        into v_existing
210	        from public.payments p
211	       where p.org_id = v_lease.org_id
212	         and p.idempotency_key = p_idempotency_key;
213	      if found then
214	        if v_existing.lease_id = p_lease_id
215	           and v_existing.amount_sen = p_amount_sen
216	           and v_existing.method = p_method
217	           and v_existing.received_at = p_received_at
218	           and v_existing.slip_path is not distinct from p_slip_path then
219	          return query select v_existing.id, v_existing.status, true;
220	          return;
221	        end if;
222	        raise exception using errcode = 'P0409', message = 'Idempotency key reused with a different payload';
223	      end if;
224	    end if;
225	    -- D22: the only other unique a manual payment can hit is slip_path (same answer as the pre-check).
226	    raise exception using errcode = 'P0400', message = 'Slip already used';
227	  end if;
228	
229	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
230	  values (v_lease.org_id, p_actor_id, 'payment.recorded', v_id,
231	          jsonb_build_object('lease_id', p_lease_id, 'amount_sen', p_amount_sen,
232	                             'method', p_method, 'status', v_status, 'received_at', p_received_at));
233	
234	  if v_status = 'approved' then
235	    perform private.allocate_payment(v_id);
236	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
237	    values (v_lease.org_id, p_actor_id, 'payment.approved', v_id,
238	            jsonb_build_object('lease_id', p_lease_id, 'amount_sen', p_amount_sen,
239	                               'allocated_sen', (select coalesce(sum(a.amount_sen), 0)
240	                                                   from public.payment_allocations a
241	                                                  where a.payment_id = v_id)));
242	  end if;
243	
244	  return query select v_id, v_status, false;
245	end;
246	$$;
247	
248	-- ---------------------------------------------------------------------------------------------
249	-- Shared lock step for approve / reject / void (D7): read the payment's lease without a lock
250	-- (lease_id is immutable), lock the lease, then lock the payment and return it fresh.
251	-- ---------------------------------------------------------------------------------------------
252	create or replace function private.lock_payment_for_manager(p_actor_id uuid, p_payment_id uuid)
253	returns public.payments
254	language plpgsql
255	security invoker
256	set search_path = ''
257	as $$
258	#variable_conflict use_column
259	declare
260	  v_lease_id uuid;
261	  v_org_id uuid;
262	  v_pay public.payments;
263	begin
264	  -- D7: the cap is computed after the lease lock; READ COMMITTED gives each statement a fresh snapshot after the wait
265	  -- (approve/reject/void call this helper first, so the guard covers all three).
266	  if current_setting('transaction_isolation') <> 'read committed' then
267	    raise exception using errcode = 'P0409', message = 'Unsupported isolation level';
268	  end if;
269	
270	  select p.lease_id, p.org_id into v_lease_id, v_org_id
271	    from public.payments p
272	   where p.id = p_payment_id;
273	  if not found then
274	    raise exception using errcode = 'P0404', message = 'Payment not found';
275	  end if;
276	
277	  -- D7: always lease before payment, the same order as record_payment, so no deadlock.
278	  perform 1 from public.leases l where l.id = v_lease_id for update;
279	
280	  -- R1/R38: only a manager of the payment's org; anyone else gets the not-found message
281	  -- (the service already answered 403 for staff of the same org before calling us).
282	  if not exists (select 1 from public.memberships m
283	                  where m.user_id = p_actor_id and m.org_id = v_org_id and m.role = 'manager') then
284	    raise exception using errcode = 'P0404', message = 'Payment not found';
285	  end if;
286	
287	  -- R28: re-read under the lock; a concurrent approve that committed first is visible now.
288	  select p.* into v_pay from public.payments p where p.id = p_payment_id for update;
289	  return v_pay;
290	end;
291	$$;
292	
293	-- ---------------------------------------------------------------------------------------------
294	-- approve_payment (R23, R26, R28)
295	-- ---------------------------------------------------------------------------------------------
296	create or replace function private.approve_payment(p_actor_id uuid, p_payment_id uuid)
297	returns table(status text)
298	language plpgsql
299	security invoker
300	set search_path = ''
301	as $$
302	#variable_conflict use_column
303	declare
304	  v_pay public.payments;
305	  v_remaining bigint;
306	begin
307	  v_pay := private.lock_payment_for_manager(p_actor_id, p_payment_id);
308	
309	  if v_pay.status <> 'pending_verification' then
310	    raise exception using errcode = 'P0409', message = 'Payment is not pending';
311	  end if;
312	
313	  -- R23/D13: re-check against invoices - allocations at this moment (pending ones ignored);
314	  -- over it -> refuse and leave the payment pending (the exception rolls back nothing else).
315	  select (select coalesce(sum(i.amount_sen), 0) from public.invoices i where i.lease_id = v_pay.lease_id)
316	       - (select coalesce(sum(a.amount_sen), 0) from public.payment_allocations a where a.lease_id = v_pay.lease_id)
317	    into v_remaining;
318	  if v_pay.amount_sen > v_remaining then
319	    raise exception using errcode = 'P0422', message = 'Payment exceeds the remaining balance';
320	  end if;
321	
322	  update public.payments p
323	     set status = 'approved', decided_by = p_actor_id, decided_at = now()
324	   where p.id = p_payment_id;
325	
326	  perform private.allocate_payment(p_payment_id);
327	
328	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
329	  values (v_pay.org_id, p_actor_id, 'payment.approved', p_payment_id,
330	          jsonb_build_object('lease_id', v_pay.lease_id, 'amount_sen', v_pay.amount_sen,
331	                             'allocated_sen', (select coalesce(sum(a.amount_sen), 0)
332	                                                 from public.payment_allocations a
333	                                                where a.payment_id = p_payment_id)));
334	
335	  return query select 'approved'::text;
336	end;
337	$$;
