418	-- ---------------------------------------------------------------------------------------------
419	-- create_gateway_bill (R30, D5): bill for what is due on or before today's Malaysia date.
420	-- ---------------------------------------------------------------------------------------------
421	create or replace function private.create_gateway_bill(
422	  p_actor_id uuid,
423	  p_lease_id uuid,
424	  p_as_of timestamptz default now()
425	)
426	returns table(id uuid, amount_sen bigint)
427	language plpgsql
428	security invoker
429	set search_path = ''
430	as $$
431	#variable_conflict use_column
432	declare
433	  v_lease record;
434	  v_today date;
435	  v_due bigint;
436	  v_id uuid;
437	begin
438	  -- D7: the cap is computed after the lease lock; READ COMMITTED gives each statement a fresh snapshot after the wait
439	  if current_setting('transaction_isolation') <> 'read committed' then
440	    raise exception using errcode = 'P0409', message = 'Unsupported isolation level';
441	  end if;
442	
443	  -- D7: lease lock so the due amount is computed against committed allocations.
444	  select l.id, l.org_id, l.tenant_id
445	    into v_lease
446	    from public.leases l
447	   where l.id = p_lease_id
448	     for update;
449	  if not found then
450	    raise exception using errcode = 'P0404', message = 'Lease not found';
451	  end if;
452	
453	  -- R1/R37: only the lease's own tenant (tenants.user_id), never another tenant or org.
454	  if not exists (select 1 from public.tenants t
455	                  where t.id = v_lease.tenant_id
456	                    and t.org_id = v_lease.org_id
457	                    and t.user_id = p_actor_id) then
458	    raise exception using errcode = 'P0404', message = 'Lease not found';
459	  end if;
460	
461	  -- D5: "today" is the Malaysia calendar date of p_as_of, never the server's zone.
462	  v_today := (p_as_of at time zone 'Asia/Kuala_Lumpur')::date;
463	
464	  -- R30/D13: unpaid amounts of invoices due on or before today; pending manual payments ignored.
465	  select coalesce(sum(greatest(i.amount_sen - coalesce((select sum(a.amount_sen)
466	                                                          from public.payment_allocations a
467	                                                         where a.invoice_id = i.id), 0), 0)), 0)
468	    into v_due
469	    from public.invoices i
470	   where i.lease_id = p_lease_id
471	     and i.due_date <= v_today;
472	
473	  if v_due <= 0 then
474	    raise exception using errcode = 'P0422', message = 'Nothing is due';
475	  end if;
476	
477	  -- R30: bill id = gen_random_uuid() column default (122 random bits, not guessable).
478	  insert into public.gateway_bills as b (org_id, lease_id, amount_sen, status, created_by)
479	  values (v_lease.org_id, p_lease_id, v_due, 'pending', p_actor_id)
480	  returning b.id into v_id;
481	
482	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
483	  values (v_lease.org_id, p_actor_id, 'gateway_bill.created', v_id,
484	          jsonb_build_object('lease_id', p_lease_id, 'amount_sen', v_due, 'as_of_date', v_today));
485	
486	  return query select v_id, v_due;
487	end;
488	$$;
