490	-- ---------------------------------------------------------------------------------------------
491	-- apply_gateway_callback (R34, R35, D10, D11): the bill state machine.
492	-- ---------------------------------------------------------------------------------------------
493	create or replace function private.apply_gateway_callback(
494	  p_bill_id uuid,
495	  p_paid boolean,
496	  p_paid_amount_sen bigint,
497	  p_paid_at timestamptz,
498	  p_transaction_id text,
499	  p_transaction_status text
500	)
501	returns table(outcome text, payment_id uuid)
502	language plpgsql
503	security invoker
504	set search_path = ''
505	as $$
506	#variable_conflict use_column
507	declare
508	  v_bill record;
509	  v_payment_id uuid;
510	begin
511	  -- D7: the cap is computed after the lease lock; READ COMMITTED gives each statement a fresh snapshot after the wait
512	  if current_setting('transaction_isolation') <> 'read committed' then
513	    raise exception using errcode = 'P0409', message = 'Unsupported isolation level';
514	  end if;
515	
516	  -- D7/D10: bill lock first; simultaneous deliveries of one callback queue here, and the second
517	  -- one sees status = 'paid' and returns 'duplicate' (R35: at most one payment per bill).
518	  select b.id, b.org_id, b.lease_id, b.amount_sen, b.status
519	    into v_bill
520	    from public.gateway_bills b
521	   where b.id = p_bill_id
522	     for update;
523	  if not found then
524	    raise exception using errcode = 'P0404', message = 'Unknown bill';
525	  end if;
526	
527	  if p_paid is null then
528	    raise exception using errcode = 'P0400', message = 'paid is required';
529	  end if;
530	
531	  -- D11/R34: amount is compared with the bill's stored amount, whatever the bill's state.
532	  if p_paid and p_paid_amount_sen is distinct from v_bill.amount_sen then
533	    raise exception using errcode = 'P0422', message = 'Paid amount does not match the bill';
534	  end if;
535	
536	  if p_paid then
537	    if v_bill.status = 'paid' then
538	      select p.id into v_payment_id from public.payments p where p.gateway_bill_id = p_bill_id;
539	      return query select 'duplicate'::text, v_payment_id;
540	      return;
541	    end if;
542	    if p_paid_at is null then
543	      raise exception using errcode = 'P0400', message = 'paid_at is required';
544	    end if;
545	
546	    -- D7: bill -> lease, the only path that takes a bill lock, so the order is never inverted.
547	    perform 1 from public.leases l where l.id = v_bill.lease_id for update;
548	
549	    update public.gateway_bills b
550	       set status = 'paid', paid_at = p_paid_at, transaction_id = p_transaction_id,
551	           transaction_status = p_transaction_status, updated_at = now()
552	     where b.id = p_bill_id;
553	
554	    -- R35: UNIQUE (gateway_bill_id) backs up the lock; on conflict we return the existing one.
555	    insert into public.payments as p
556	           (org_id, lease_id, amount_sen, method, status, received_at, gateway_bill_id, decided_at)
557	    values (v_bill.org_id, v_bill.lease_id, v_bill.amount_sen, 'online', 'approved', p_paid_at,
558	            p_bill_id, now())
559	    on conflict do nothing
560	    returning p.id into v_payment_id;
561	
562	    if v_payment_id is null then
563	      select p.id into v_payment_id from public.payments p where p.gateway_bill_id = p_bill_id;
564	      return query select 'duplicate'::text, v_payment_id;
565	      return;
566	    end if;
567	
568	    -- R26: allocate like any approval; what the invoices cannot absorb becomes unapplied_sen
569	    -- (captured money is never refused).
570	    perform private.allocate_payment(v_payment_id);
571	
572	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
573	    values (v_bill.org_id, null, 'gateway_bill.paid', p_bill_id,
574	            jsonb_build_object('lease_id', v_bill.lease_id, 'payment_id', v_payment_id,
575	                               'amount_sen', v_bill.amount_sen, 'transaction_id', p_transaction_id,
576	                               'transaction_status', p_transaction_status, 'paid_at', p_paid_at));
577	
578	    -- R25: every approval is audited; a gateway payment is approved by the system (actor null).
579	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
580	    values (v_bill.org_id, null, 'payment.approved', v_payment_id,
581	            jsonb_build_object('source', 'gateway', 'bill_id', p_bill_id));
582	
583	    return query select 'paid'::text, v_payment_id;
584	    return;
585	  end if;
586	
587	  -- paid = false: only a pending bill moves (to failed); failed stays failed, paid never goes back.
588	  if v_bill.status = 'pending' then
589	    update public.gateway_bills b
590	       set status = 'failed', transaction_id = p_transaction_id,
591	           transaction_status = p_transaction_status, updated_at = now()
592	     where b.id = p_bill_id;
593	
594	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
595	    values (v_bill.org_id, null, 'gateway_bill.failed', p_bill_id,
596	            jsonb_build_object('lease_id', v_bill.lease_id, 'transaction_id', p_transaction_id,
597	                               'transaction_status', p_transaction_status));
598	
599	    return query select 'failed'::text, null::uuid;
600	    return;
601	  end if;
602	
603	  return query select 'ignored'::text, null::uuid;
604	end;
605	$$;
606	
607	-- D8: owner-only. Not callable by anon/authenticated even if the private schema were exposed.
608	revoke execute on function private.allocate_payment(uuid) from public, anon, authenticated;
609	revoke execute on function private.record_payment(uuid, uuid, bigint, text, timestamptz, text, uuid) from public, anon, authenticated;
610	revoke execute on function private.lock_payment_for_manager(uuid, uuid) from public, anon, authenticated;
611	revoke execute on function private.approve_payment(uuid, uuid) from public, anon, authenticated;
612	revoke execute on function private.reject_payment(uuid, uuid, text) from public, anon, authenticated;
613	revoke execute on function private.void_payment(uuid, uuid, text) from public, anon, authenticated;
614	revoke execute on function private.create_gateway_bill(uuid, uuid, timestamptz) from public, anon, authenticated;
615	revoke execute on function private.apply_gateway_callback(uuid, boolean, bigint, timestamptz, text, text) from public, anon, authenticated;
