3	// D2: every error body is { "error": "<message>" }, a plain string (brief section 7).
4	export class ApiError extends Error {
5	  readonly status: number
6	
7	  constructor(status: number, message: string) {
8	    super(message)
9	    this.name = 'ApiError'
10	    this.status = status
11	  }
12	}
13	
14	export const badRequest = (msg = 'Invalid input') => new ApiError(400, msg)
15	export const unauthorized = (msg = 'Unauthorized') => new ApiError(401, msg)
16	export const forbidden = (msg = 'Forbidden') => new ApiError(403, msg)
17	export const notFound = (msg = 'Not found') => new ApiError(404, msg)
18	export const conflict = (msg = 'Conflict') => new ApiError(409, msg)
19	export const unprocessable = (msg = 'Unprocessable') => new ApiError(422, msg)
20	
21	export function errorResponse(status: number, message: string): Response {
22	  return Response.json({ error: message }, { status })
23	}
24	
25	type PgError = { code: string; message: string }
26	
27	function isRecord(v: unknown): v is Record<string, unknown> {
28	  return typeof v === 'object' && v !== null
29	}
30	
31	// Finds the Postgres SQLSTATE behind an error, wherever the stack put it:
32	// - Prisma 7 + adapter-pg: PrismaClientKnownRequestError.meta.driverAdapterError.cause.{originalCode, originalMessage}
33	//   ($queryRaw failures arrive as P2010 with the real SQLSTATE only there);
34	// - a bare DriverAdapterError (.cause.originalCode), or a pg DatabaseError (.code + .severity).
35	function findPgError(e: unknown, depth = 0): PgError | null {
36	  if (!isRecord(e) || depth > 4) return null
37	  if (typeof e.originalCode === 'string') {
38	    return { code: e.originalCode, message: typeof e.originalMessage === 'string' ? e.originalMessage : '' }
39	  }
40	  if (typeof e.code === 'string' && /^[0-9A-Z]{5}$/.test(e.code) && typeof e.severity === 'string') {
41	    return { code: e.code, message: typeof e.message === 'string' ? e.message : '' }
42	  }
43	  if (isRecord(e.meta)) {
44	    const found = findPgError(e.meta.driverAdapterError, depth + 1)
45	    if (found) return found
46	  }
47	  return findPgError(e.cause, depth + 1)
48	}
49	
50	function prismaCode(e: unknown): string | null {
51	  return isRecord(e) && typeof e.code === 'string' && /^P\d{4}$/.test(e.code) ? e.code : null
52	}
53	
54	const RETRYABLE_SQLSTATES = new Set(['40001', '40P01'])
55	
56	export function isRetryable(e: unknown): boolean {
57	  const pg = findPgError(e)
58	  if (pg) return RETRYABLE_SQLSTATES.has(pg.code)
59	  return prismaCode(e) === 'P2034'
60	}
61	
62	// Error contract: serialization failure / deadlock is retried once, then surfaces as 409.
63	export async function withRetry<T>(fn: () => Promise<T>): Promise<T> {
64	  try {
65	    return await fn()
66	  } catch (e) {
67	    if (!isRetryable(e)) throw e
68	    return fn()
69	  }
70	}
71	
72	function zodMessage(e: ZodError): string {
73	  const issue = e.issues[0]
74	  if (!issue) return 'Invalid input'
75	  const path = issue.path.map(String).join('.')
76	  return path ? `Invalid input: ${path}: ${issue.message}` : `Invalid input: ${issue.message}`
77	}
78	
79	const DB_CODE_STATUS: Record<string, { status: number; message: string | null }> = {
80	  // private.* functions raise these with a human message that is safe to show (SPEC money functions).
81	  P0400: { status: 400, message: null },
82	  P0404: { status: 404, message: null },
83	  P0409: { status: 409, message: null },
84	  P0422: { status: 422, message: null },
85	  '23P01': { status: 409, message: 'Lease overlaps another lease on this unit' }, // D16
86	  '23505': { status: 409, message: 'Conflict with an existing record' },
87	  '22P02': { status: 400, message: 'Invalid input' },
88	  '22007': { status: 400, message: 'Invalid input' },
89	  '22008': { status: 400, message: 'Invalid input' },
90	  '23503': { status: 400, message: 'Invalid reference' },
91	  '23514': { status: 400, message: 'Invalid input' },
92	  '23502': { status: 400, message: 'Invalid input' },
93	  '40001': { status: 409, message: 'Conflict with a concurrent request, please retry' },
94	  '40P01': { status: 409, message: 'Conflict with a concurrent request, please retry' },
95	}
96	
97	const PRISMA_CODE_STATUS: Record<string, { status: number; message: string }> = {
98	  P2002: { status: 409, message: 'Conflict with an existing record' },
99	  P2025: { status: 404, message: 'Not found' },
100	  P2023: { status: 400, message: 'Invalid input' },
101	  P2003: { status: 400, message: 'Invalid reference' },
102	  P2034: { status: 409, message: 'Conflict with a concurrent request, please retry' },
103	}
104	
105	export function toErrorResponse(e: unknown): Response {
106	  if (e instanceof ApiError) return errorResponse(e.status, e.message)
107	  if (e instanceof ZodError) return errorResponse(400, zodMessage(e))
108	
109	  const pg = findPgError(e)
110	  if (pg) {
111	    const mapped = DB_CODE_STATUS[pg.code]
112	    if (mapped) {
113	      const fallback = mapped.status === 404 ? 'Not found' : 'Invalid request'
114	      return errorResponse(mapped.status, mapped.message ?? (pg.message.trim() || fallback))
115	    }
116	  }
117	  const pc = prismaCode(e)
118	  if (pc && PRISMA_CODE_STATUS[pc]) {
119	    const { status, message } = PRISMA_CODE_STATUS[pc]
120	    return errorResponse(status, message)
121	  }
122	
123	  // Generic 500: only the error class and code are logged (no payloads, no SQL, no secrets).
124	  const name = isRecord(e) && typeof e.name === 'string' ? e.name : typeof e
125	  console.error('[api] unhandled error', { name, code: pg?.code ?? pc ?? null })
126	  return errorResponse(500, 'Internal error')
127	}
